  ('found', 'found%2:41:00::', 'found%2:41:00::', 0, 'verb', NULL, 'set up or found', 'She set up a literacy program'),
  ('found', 'found%2:36:00::', 'found%2:36:00::', 0, 'verb', NULL, 'set up or lay the groundwork for', 'establish a new department'),
  ('found', 'found%2:31:00::', 'found%2:31:00::', 0, 'verb', NULL, 'use as a basis for; found on', 'base a claim on some observation'),
  ('blog', 'blog%1:10:00::', 'blog%1:10:00::', 0, 'noun', NULL, 'a shared on-line journal where people can post diary entries about their personal experiences and hobbies', 'postings on a blog are usually in chronological order'),
  ('blog', 'blog%2:32:00::', 'blog%2:32:00::', 0, 'verb', NULL, 'read, write, or edit a shared on-line journal', NULL),
  ('thirst', 'thirst%1:26:00::', 'thirst%1:26:00::', 0, 'noun', '/θɝst/', 'a physiological need to drink', NULL),
  ('thirst', 'thirst%1:07:00::', 'thirst%1:07:00::', 0, 'noun', '/θɝst/', 'strong desire for something (not food or drink)', 'a thirst for knowledge'),
  ('thirst', 'thirst%2:39:00::', 'thirst%2:39:00::', 0, 'verb', '/θɝst/', 'feel the need to drink', NULL),
  ('thirst', 'thirst%2:34:00::', 'thirst%2:34:00::', 0, 'verb', '/θɝst/', 'have a craving, appetite, or great desire for', NULL)
) AS v(normalized_word, source_entry_ref, sense_key, priority, part_of_speech, phonetic, definition_en, sentence)
JOIN public.lexemes AS l ON l.language = 'en' AND l.normalized_word = v.normalized_word
ON CONFLICT (lexeme_id, source_id, sense_key) DO UPDATE SET
  source_entry_ref = EXCLUDED.source_entry_ref,
  priority = GREATEST(public.lexicon_entries.priority, EXCLUDED.priority),
  part_of_speech = EXCLUDED.part_of_speech, phonetic = EXCLUDED.phonetic,
  definition_en = EXCLUDED.definition_en, sentence = EXCLUDED.sentence;

DO $$
DECLARE
  _sense_count bigint;
  _lexeme_count bigint;
  _reviewed_count bigint;
  _pilot_key_count bigint;
  _unreviewed_count bigint;
  _provenance_count bigint;
BEGIN
  SELECT count(*), count(DISTINCT lexeme_id), count(*) FILTER (WHERE priority=100), count(*) FILTER (WHERE priority=0)
    INTO _sense_count, _lexeme_count, _reviewed_count, _unreviewed_count
    FROM public.lexicon_entries WHERE source_id='oewn-2025';
  IF (_sense_count, _lexeme_count, _reviewed_count, _unreviewed_count) IS DISTINCT FROM (19028, 2742, 26, 19002) THEN
    RAISE EXCEPTION 'OEWN postflight count mismatch: senses %, lexemes %, reviewed %, unreviewed %', _sense_count, _lexeme_count, _reviewed_count, _unreviewed_count;
  END IF;
  SELECT count(*) INTO _pilot_key_count FROM public.lexicon_entries
    WHERE source_id='oewn-2025' AND priority=100 AND sense_key IN ('ability%1:07:00::', 'achieve%2:41:00::', 'adapt%2:30:01::', 'analyze%2:31:00::', 'bank%1:14:00::', 'book%1:10:00::', 'challenge%1:26:00::', 'concept%1:09:00::', 'create%2:36:00::', 'decision%1:04:00::', 'develop%2:36:01::', 'effort%1:04:00::', 'evidence%1:09:00::', 'familiar%3:00:00::', 'focus%1:09:00::', 'garden%1:06:00::', 'hospital%1:06:00::', 'identify%2:31:00::', 'improve%2:30:01::', 'learn%2:31:00::', 'library%1:06:01::', 'maintain%2:42:00::', 'music%1:10:00::', 'perform%2:36:00::', 'teacher%1:18:00::', 'water%1:27:00::');
  IF _pilot_key_count <> 26 THEN RAISE EXCEPTION 'Reviewed pilot sense postflight check failed'; END IF;
  SELECT count(*) INTO _provenance_count FROM public.lexicon_sources
    WHERE id='oewn-2025' AND version='2025-12-31' AND license_id='CC-BY-4.0' AND source_sha256='7d749f6e2c39e6970e4997839dcf6e42fd281f3c2fae0171d2192bae8cfa4b51'
      AND source_url='https://en-word.net/downloads/english-wordnet-2025-json.zip' AND license_url='https://github.com/globalwordnet/english-wordnet/blob/2025-edition/LICENSE.md' AND length(license_notice)>0;
  IF _provenance_count <> 1 THEN RAISE EXCEPTION 'OEWN source provenance postflight check failed'; END IF;
END $$;

COMMIT;

SELECT b.lexemes_total AS lexemes_before, (SELECT count(*) FROM public.lexemes) AS lexemes_after,
       (SELECT count(*) FROM public.lexicon_entries) AS all_senses_after,
       b.oewn_lexemes AS oewn_lexemes_before,
       (SELECT count(DISTINCT lexeme_id) FROM public.lexicon_entries WHERE source_id='oewn-2025') AS oewn_lexemes_after,
       b.oewn_senses AS oewn_senses_before,
       (SELECT count(*) FROM public.lexicon_entries WHERE source_id='oewn-2025') AS oewn_senses_after,
       b.sources_total AS sources_before, (SELECT count(*) FROM public.lexicon_sources) AS sources_after,
       (SELECT count(*) FROM public.lexicon_sources WHERE id='oewn-2025' AND source_sha256='7d749f6e2c39e6970e4997839dcf6e42fd281f3c2fae0171d2192bae8cfa4b51' AND version='2025-12-31') AS verified_oewn_provenance_rows
FROM oewn_import_baseline AS b;
